terraform {
  required_version = ">= 1.0.0"
}

variable "scope" {
  type    = string
  default = "CLOUDFRONT"
}

resource "aws_wafv2_web_acl" "default" {
  name  = "default-${var.scope}-web-acl"
  scope = var.scope

  default_action {
    block {}
  }

  # static managed rule group (common)
  rule {
    name     = "rule-${var.scope}-AWSManagedRulesCommonRuleSet"
    priority = 1

    override_action {
      none {}
    }

    statement {
      managed_rule_group_statement {
        name        = "AWSManagedRulesCommonRuleSet"
        vendor_name = "AWS"
      }
    }

    visibility_config {
      cloudwatch_metrics_enabled = true
      metric_name                = "rule-${var.scope}-AWSManagedRulesCommonRuleSet"
      sampled_requests_enabled   = true
    }
  }

  # static managed rule group (KnownBadInputs) that CKV_AWS_192 expects
  rule {
    name     = "AWS-AWSManagedRulesKnownBadInputsRuleSet"
    priority = 2

    override_action {
      none {}
    }

    statement {
      managed_rule_group_statement {
        name        = "AWSManagedRulesKnownBadInputsRuleSet"
        vendor_name = "AWS"
      }
    }

    visibility_config {
      cloudwatch_metrics_enabled = true
      metric_name                = "rule-${var.scope}-AWSManagedRulesKnownBadInputsRuleSet"
      sampled_requests_enabled   = true
    }
  }

  # dynamic rule 1
  dynamic "rule" {
    for_each = [1]

    content {
      name     = "rule-${var.scope}-ip-allowlist"
      priority = 8

      action {
        allow {}
      }

      statement {
        or_statement {
          statement {
            ip_set_reference_statement {
              arn = "arn:aws:wafv2:region:acct:ipset/allow1"
            }
          }
          statement {
            ip_set_reference_statement {
              arn = "arn:aws:wafv2:region:acct:ipset/allow2"
            }
          }
        }
      }

      visibility_config {
        cloudwatch_metrics_enabled = true
        metric_name                = "rule-${var.scope}-ip-allowlist"
        sampled_requests_enabled   = true
      }
    }
  }

  # dynamic rule 2
  dynamic "rule" {
    for_each = [1]

    content {
      name     = "rule-${var.scope}-review-token-check"
      priority = 30

      action {
        allow {}
      }

      statement {
        byte_match_statement {
          positional_constraint = "EXACTLY"
          search_string         = "sometoken"

          field_to_match {
            single_header {
              name = "review-token"
            }
          }

          text_transformation {
            priority = 1
            type     = "NONE"
          }
        }
      }

      visibility_config {
        cloudwatch_metrics_enabled = true
        metric_name                = "rule-${var.scope}-review-token-check"
        sampled_requests_enabled   = true
      }
    }
  }

  visibility_config {
    cloudwatch_metrics_enabled = true
    metric_name                = "${var.scope}-web-acl"
    sampled_requests_enabled   = true
  }
}

